const firstIndex = new Map()
const letters = ['x', 'y', 'x', 'z']
letters.forEach((letter, i) => {
  if (!firstIndex.has(letter)) firstIndex.set(letter, i)
})
console.log(firstIndex.get('x'), firstIndex.get('z'))

